import sys

def main():
    s, t = sys.stdin.read().split()[:2]
    m = len(t)
    fail = [0] * m
    k = 0
    for i in range(1, m):
        while k and t[i] != t[k]:
            k = fail[k - 1]
        if t[i] == t[k]:
            k += 1
        fail[i] = k
    k = 0
    ans = -1
    for i, ch in enumerate(s):
        while k and ch != t[k]:
            k = fail[k - 1]
        if ch == t[k]:
            k += 1
        if k == m:
            ans = i - m + 1
            break
    print(ans)

